/* Light: Neutral and quiet: the reference look. */
[data-example-theme="light"] {
    --floor: rgb(255, 255, 255);
    --ink: rgb(20, 20, 20);
}

/* Dark: The same shapes as Light, on dark palettes. */
[data-example-theme="dark"] {
    --floor: rgb(17, 24, 39);
    --ink: rgb(240, 240, 240);
}

/* IDE: A dense code-editor planner: hairline grid, square events with a stripe. */
[data-example-theme="ide"] {
    --floor: rgb(30, 32, 40);
    --ink: rgb(220, 225, 235);
}

/* Paper: Warm and spacious: tall slots, rounded events, a serif face, dotted lines. */
[data-example-theme="paper"] {
    --floor: rgb(245, 239, 224);
    --ink: rgb(60, 40, 20);
}

/* Terminal: Phosphor green on black: monospace, square cells, dashed lines. */
[data-example-theme="terminal"] {
    --floor: rgb(0, 26, 0);
    --ink: rgb(120, 255, 120);
}
